sys_generative_ai_custom_llm_transformer.request_transformer:
(function(inputs) {
    /*
    write code here to construct the request body and any
    custom headers needed using the inputs object.
    inputs structure: {
        prompt_data: object,
        request_data: object
    }
    */
    var requestData = inputs.request_data;
    var promptData = inputs.prompt_data;
    var prompt = promptData.prompt;

    var body = {
        model: "gpt-4o",
        messages: [{
            "role": "user",
            "content": prompt
        }],
        max_tokens: 700
    };

    var headers = {};

    return {
        body: body,
        headers: headers
    };
})(inputs);

sys_generative_ai_custom_llm_transformer.response_transformer:
(function(inputs) {
    /*
    write code here to transform the llm response into an
    array of text responses, using the inputs object
    inputs structure: {
        prompt_data: object,
        request_data: object,
        response_body: string,
        response_headers: string
    }
    */
    var requestData = inputs.request_data;
    var promptData = inputs.prompt_data;
    var responseBody = JSON.parse(inputs.response_body);

    var responseTexts = [];
    responseTexts.push(responseBody.choices[0].message.content);

    return responseTexts;
})(inputs);
